insert into public.pages (id, title, slug, status, display_order, is_featured, data, published_data) values ('00000000-0000-4000-8000-000000000011', 'Home', 'home', 'published', 11, false, '{"seo_title":"RADAR Centre | Rajalakshmi Institute of Technology","seo_description":"Engineering a healthier tomorrow. Explore interdisciplinary healthcare research at RADAR Centre, Rajalakshmi Institute of Technology.","sections":[{"id":"section-1","type":"hero","visible":true,"variant":"default","data":{"eyebrow":"RAJALAKSHMI INSTITUTE OF TECHNOLOGY · FUTURE TECH RIT","heading":"Engineering a\nhealthier tomorrow.","description":"Advancing healthcare through interdisciplinary research in medical imaging, radiomics, artificial intelligence and emerging engineering technologies.","button_label":"Explore our research","button_url":"/research","secondary_label":"Discover RADAR","secondary_url":"/about"}},{"id":"section-2","type":"quote","visible":true,"variant":"light","data":{"quote_text":"Where engineering meets human wellbeing, innovation finds its purpose.","attribution":"RADAR Centre"}},{"id":"section-3","type":"editorial","visible":true,"variant":"split","data":{"eyebrow":"01 / MEET RADAR","heading":"Research beyond\nboundaries.","description":"The RADAR Centre is an interdisciplinary research initiative of Future Tech RIT, working at the intersection of healthcare, medical imaging, radiomics, artificial intelligence and emerging engineering technologies.","button_label":"The centre & our purpose","button_url":"/about"}},{"id":"section-4","type":"research","visible":true,"variant":"default","data":{"eyebrow":"02 / OUR RESEARCH","heading":"Different disciplines.\nOne human purpose.","description":"Exploring the connections between engineering, intelligence and better healthcare.","button_label":"Explore all research","button_url":"/research","limit":6}},{"id":"section-5","type":"members","visible":true,"variant":"default","data":{"eyebrow":"03 / OUR PEOPLE","heading":"The people behind\nthe possibilities.","description":"An interdisciplinary community of faculty members and students working together to translate research ideas into meaningful healthcare solutions.","button_label":"Meet our members","button_url":"/members","limit":4}},{"id":"section-6","type":"events","visible":true,"variant":"light","data":{"eyebrow":"04 / LIFE AT RADAR","heading":"Moments of discovery.","description":"From educational outreach to exhibitions and collaborative learning, research moves forward when ideas are shared.","button_label":"All events & activities","button_url":"/events","limit":3}},{"id":"section-7","type":"projects","visible":true,"variant":"default","data":{"eyebrow":"05 / INNOVATION IN ACTION","heading":"Ideas becoming impact.","description":"Student-led projects and interdisciplinary research developed through the RADAR Centre.","button_label":"Explore our projects","button_url":"/projects","limit":3}},{"id":"section-8","type":"vision","visible":true,"variant":"light","data":{"eyebrow":"06 / OUR NORTH STAR","heading":"Better diagnostics.\nMore possibilities.","description":"To advance healthcare diagnosis through interdisciplinary research, integrating medical imaging, radiomics, AI and emerging technologies to develop innovative, accurate, non-invasive and accessible diagnostic solutions.","mission":["Conduct interdisciplinary research integrating medical imaging, radiomics, artificial intelligence, RF and microwave engineering, biomedical sensing and emerging technologies.","Develop innovative, accurate, non-invasive, affordable and intelligent diagnostic technologies.","Bridge engineering and clinical expertise through collaboration with medical professionals, academic institutions, industry partners and researchers.","Foster a research-driven ecosystem with mentorship, hands-on training, computational tools and experimental facilities."],"objectives":["Promote interdisciplinary research.","Develop practical diagnostic technologies.","Esta