ologies.","Develop innovative, accurate, non-invasive, affordable and intelligent diagnostic technologies.","Bridge engineering and clinical expertise through collaboration with medical professionals, academic institutions, industry partners and researchers.","Foster a research-driven ecosystem with mentorship, hands-on training, computational tools and experimental facilities."],"objectives":["Promote interdisciplinary research.","Develop practical diagnostic technologies.","Establish clinical, academic and industry collaborations.","Translate research concepts into meaningful healthcare applications."]}},{"id":"section-9","type":"achievements","visible":true,"variant":"default","data":{"eyebrow":"07 / RESEARCH NOTES","heading":"Research. Recognition. Progress.","description":"Faculty contributions recorded in the July–August 2026 activity summary.","limit":3}},{"id":"section-10","type":"cta","visible":true,"variant":"dark","data":{"eyebrow":"A SHARED PURPOSE","heading":"Technology becomes meaningful when it makes a difference in someone’s life.","description":"RADAR Centre","button_label":"Connect with RADAR","button_url":"/contact"}}]}') on conflict (id) do nothing;
insert into public.pages (id, title, slug, status, display_order, is_featured, data, published_data) values ('00000000-0000-4000-8000-000000000018', 'About RADAR', 'about', 'published', 18, false, '{"seo_description":"The RADAR Centre is an interdisciplinary research initiative of Future Tech RIT, working at the intersection of healthcare, medical imaging, radiomics, artificial intelligence and emerging engineering technologies.","sections":[{"id":"section-13","type":"editorial","visible":true,"variant":"split","data":{"eyebrow":"ABOUT THE CENTRE","heading":"At the intersection of\nengineering & wellbeing.","description":"The RADAR Centre is an interdisciplinary research initiative of Future Tech RIT, working at the intersection of healthcare, medical imaging, radiomics, artificial intelligence and emerging engineering technologies."}},{"id":"section-14","type":"columns","visible":true,"variant":"default","data":{"eyebrow":"OUR APPROACH","heading":"Curiosity, with purpose.","description":"Our aim is to translate technological research into reliable, affordable and impactful solutions for real-world healthcare challenges.","second_heading":"Collaboration, by design.","second_description":"Bringing engineering and clinical perspectives together is central to our mission. We welcome conversations with researchers, healthcare professionals and industry partners."}},{"id":"section-15","type":"vision","visible":true,"variant":"light","data":{"eyebrow":"VISION · MISSION · OBJECTIVES","heading":"A clear direction.\nA shared responsibility.","description":"To advance healthcare diagnosis through interdisciplinary research, integrating medical imaging, radiomics, AI and emerging technologies to develop innovative, accurate, non-invasive and accessible diagnostic solutions.","mission":["Conduct interdisciplinary research integrating medical imaging, radiomics, artificial intelligence, RF and microwave engineering, biomedical sensing and emerging technologies.","Develop innovat