insert into public.events (id, title, slug, status, display_order, is_featured, data, published_data) values ('00000000-0000-4000-8000-000000000045', 'Outreach Programme at Aditya Vidhyashram', 'outreach-aditya-august-2026', 'published', 45, true, '{"category":"Outreach","start_date":"2026-08-20","venue":"Aditya Vidhyashram School","short_description":"Introducing healthcare and assistive technology through student-led demonstrations.","full_description":"RADAR demonstrated the AI-Based Medical Scan Risk Assessment and Smart Alert System, alongside a Blind Stick for assisting visually impaired individuals.","related_projects":["blind-stick"],"participants":[]}', '{"category":"Outreach","start_date":"2026-08-20","venue":"Aditya Vidhyashram School","short_description":"Introducing healthcare and assistive technology through student-led demonstrations.","full_description":"RADAR demonstrated the AI-Based Medical Scan Risk Assessment and Smart Alert System, alongside a Blind Stick for assisting visually impaired individuals.","related_projects":["blind-stick"],"participants":[]}') on conflict (id) do nothing;
insert into public.events (id, title, slug, status, display_order, is_featured, data, published_data) values ('00000000-0000-4000-8000-000000000046', 'Project Exhibition', 'project-exhibition-august-2026', 'published', 46, false, '{"category":"Exhibitions","start_date":"2026-08-15","venue":"Aditya Vidhyashram School","short_description":"Student ideas, technical knowledge and a conversation about the possibilities of engineering.","full_description":"Sanjay Y and Rishan N of III ECE-C showcased their project and demonstrated their technical knowledge and presentation skills. Dr. Daniel Chellappa, Former Nuclear Scientist, visited the demonstration and appreciated the team’s work.","participants":["Sanjay Y — III ECE-C","Rishan N — III ECE-C"]}', '{"category":"Exhibitions","start_date":"2026-08-15","venue":"Aditya Vidhyashram School","short_description":"Student ideas, technical knowledge and a conversation about the possibilities of engineering.","full_description":"Sanjay Y and Rishan N of III ECE-C showcased their project and demonstrated their technical knowledge and presentation skills. Dr. Daniel Chellappa, Former Nuclear Scientist, visited the demonstration and appreciated the team’s work.","participants":["Sanjay Y — III ECE-C","Rishan N — III ECE-C"]}') on conflict (id) do nothing;
