insert into public.events (id, title, slug, status, display_order, is_featured, data, published_data) values ('00000000-0000-4000-8000-000000000048', 'Outreach Programme at JVVM', 'outreach-jvvm-july-2026', 'published', 48, false, '{"category":"Outreach","start_date":"2026-07-25","venue":"JVVM School","short_description":"Demonstrating smart posture monitoring and the potential of blood donor applications.","full_description":"RADAR student members demonstrated a smart posture detection system for paralysis patients and a blood donor application to introduce school students to healthcare technology and student-led innovation.","outcomes":"Participants gained awareness of smart posture monitoring and the potential of blood donor applications in connecting patients with donors.","related_projects":["smart-posture-detection","blood-donor-application"]}', '{"category":"Outreach","start_date":"2026-07-25","venue":"JVVM School","short_description":"Demonstrating smart posture monitoring and the potential of blood donor applications.","full_description":"RADAR student members demonstrated a smart posture detection system for paralysis patients and a blood donor application to introduce school students to healthcare technology and student-led innovation.","outcomes":"Participants gained awareness of smart posture monitoring and the potential of blood donor applications in connecting patients with donors.","related_projects":["smart-posture-detection","blood-donor-application"]}') on conflict (id) do nothing;
